<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model; class LetterRequest extends Model { protected $fillable=['request_number','letter_type_id','applicant_id','laboratory_id','subject','notes','status','current_step_order','completed_at']; protected $casts=['completed_at'=>'datetime']; public function letterType(){return $this->belongsTo(LetterType::class);} public function applicant(){return $this->belongsTo(User::class,'applicant_id');} public function laboratory(){return $this->belongsTo(Laboratory::class);} public function histories(){return $this->hasMany(LetterRequestHistory::class)->orderBy('created_at');} public function files(){return $this->hasMany(LetterRequirementSubmission::class);} public function currentStep(){return $this->belongsTo(LetterWorkflowStep::class,'current_step_order','step_order')->whereColumn('letter_workflow_steps.letter_type_id','letter_requests.letter_type_id');} }
